const tareaInput=document.getElementById("tareaInput"),agregarBtn=document.getElementById("agregarBtn"),listaTareas=document.getElementById("listaTareas"),contador=document.getElementById("contador"),limpiarBtn=document.getElementById("limpiarBtn");let tareas=[];function agregarTarea(){const e=tareaInput.value.trim();""===e?(alert("Escribe una tarea."),void 0):(tareas.push({texto:e,completada:!1}),tareaInput.value="",mostrarTareas())}function mostrarTareas(){listaTareas.innerHTML="",tareas.forEach((e,t)=>{const a=document.createElement("li");a.className="tarea",e.completada&&a.classList.add("completada");const r=document.createElement("span");r.textContent=e.texto,r.addEventListener("click",()=>{tareas[t].completada=!tareas[t].completada,mostrarTareas()});const o=document.createElement("button");o.textContent="Eliminar",o.className="eliminar",o.addEventListener("click",()=>{tareas.splice(t,1),mostrarTareas()}),a.appendChild(r),a.appendChild(o),listaTareas.appendChild(a)}),actualizarContador()}function actualizarContador(){const e=tareas.filter(e=>!e.completada).length;contador.textContent=1===e?"1 tarea pendiente":`${e} tareas pendientes`}limpiarBtn.addEventListener("click",()=>{tareas=tareas.filter(e=>!e.completada),mostrarTareas()}),agregarBtn.addEventListener("click",agregarTarea),tareaInput.addEventListener("keypress",e=>{"Enter"===e.key&&agregarTarea()}),mostrarTareas();
